 static boolean valid(File file)throws Exception{if(!file.isFile()||file.length()!=BYTES)return false;MessageDigest digest=MessageDigest.getInstance("SHA-1");try(InputStream in=new FileInputStream(file)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)digest.update(b,0,n);}StringBuilder h=new StringBuilder();for(byte b:digest.digest())h.append(String.format("%02x",b&255));return h.toString().equals(HASH);}
 static JSONObject state(MainActivity a)throws Exception{JSONObject v=new JSONObject();v.put("busy",busy.get());v.put("phase",phase);v.put("received",received);v.put("bytes",BYTES);v.put("seconds",started>0?(System.currentTimeMillis()-started)/1000.0:0);v.put("progress",phase.equals("transcribing")?progressNative():0);v.put("installed",model(a).isFile()&&model(a).length()==BYTES);v.put("model","Whisper base multilingual · CPU");return v;}
 static void cancel(){cancelled.set(true);cancelNative();}
