 static void install(MainActivity a,String id)throws Exception{begin("verifying model");try{File input=a.mediaFile(id);if(!valid(input))throw new IOException("Choose the original ggml-base.bin (multilingual, 142 MiB); checksum did not match");if(cancelled.get())throw new IOException("Cancelled");File target=model(a);if(target.exists())target.delete();if(!input.renameTo(target))throw new IOException("Model could not be activated");}finally{phase="idle";busy.set(false);}}
